"use client";
import { useState, useEffect, useCallback } from 'react';
import { publicClient, getWalletClient } from '@/lib/client';
import ClaimHandle from '@/components/ClaimHandle';
import ProfileHeader from '@/components/ProfileHeader';

export default function Home() {
  const [account, setAccount] = useState<string | null>(null);
  const [hasHandle, setHasHandle] = useState<boolean>(false);
  const [loading, setLoading] = useState(true);

  // Function to check if the user exists in the Registry
  const checkHandle = useCallback(async (address: string) => {
    try {
      const profile = await publicClient.readContract({
        address: process.env.NEXT_PUBLIC_REGISTRY_ADDR as `0x${string}`,
        abi: [{
          name: 'getProfile',
          type: 'function',
          stateMutability: 'view',
          inputs: [{ name: '_user', type: 'address' }],
          outputs: [{ name: 'username', type: 'string' }, { name: 'metadataCID', type: 'string' }],
        }],
        functionName: 'getProfile',
        args: [address as `0x${string}`],
      });
      
      // If a username is returned, the user has a handle
      setHasHandle(!!profile[0]);
    } catch (e) {
      setHasHandle(false);
    }
  }, []);

  // Check connection and handle on page load (Refresh-Proof)
  useEffect(() => {
    const init = async () => {
      const client = await getWalletClient();
      if (client) {
        const addresses = await client.getAddresses();
        if (addresses.length > 0) {
          setAccount(addresses[0]);
          await checkHandle(addresses[0]);
        }
      }
      setLoading(false);
    };
    init();
  }, [checkHandle]);

  const connect = async () => {
    const client = await getWalletClient();
    if (client) {
      const [address] = await client.requestAddresses();
      setAccount(address);
      await checkHandle(address);
    }
  };

  if (loading) return (
    <div className="min-h-screen bg-black flex items-center justify-center">
      <p className="text-zinc-500 font-bold animate-pulse">SYNCING HARD FORK...</p>
    </div>
  );

  return (
    <main className="min-h-screen bg-black text-white p-6">
      <div className="max-w-xl mx-auto">
        
        {/* Navigation */}
        <header className="flex justify-between items-center mb-12">
          <h1 className="text-3xl font-black italic tracking-tighter">HARD FORK</h1>
          <button 
            onClick={connect} 
            className="bg-zinc-900 hover:bg-zinc-800 px-6 py-2.5 rounded-full text-sm font-bold border border-zinc-800 transition-all"
          >
            {account ? `${account.slice(0,6)}...${account.slice(-4)}` : "Connect Wallet"}
          </button>
        </header>

        {/* Content Area */}
        {!account ? (
          <div className="text-center py-24 bg-zinc-900/30 rounded-[2.5rem] border border-zinc-900 border-dashed">
            <h2 className="text-2xl font-bold mb-3">Venture is On-Chain</h2>
            <p className="text-zinc-500 mb-8 max-w-xs mx-auto text-sm">Connect your XDC wallet to join the next generation of creators.</p>
            <button 
              onClick={connect} 
              className="bg-white text-black px-10 py-4 rounded-2xl font-black hover:bg-zinc-200 transition-transform active:scale-95"
            >
              Connect Wallet
            </button>
          </div>
        ) : (
          <div className="space-y-8">
            {/* Logic: Show Header if handle exists, otherwise show Claim form */}
            {hasHandle ? (
              <ProfileHeader account={account} />
            ) : (
              <ClaimHandle 
                account={account} 
                onSuccess={() => checkHandle(account)} 
              />
            )}

            {/* FEED SECTION */}
            <div className="pt-8">
               <div className="flex items-center gap-4 mb-6">
                 <p className="text-zinc-500 font-black uppercase text-[10px] tracking-[0.2em]">The Venture Feed</p>
                 <div className="h-[1px] flex-1 bg-zinc-900" />
               </div>
               
               <div className="bg-zinc-900/50 p-10 rounded-[2rem] border border-zinc-900 text-center">
                 <p className="text-zinc-600 font-medium italic">Ready to share your first update, @balson?</p>
               </div>
            </div>
          </div>
        )}
      </div>
    </main>
  );
}